(function(g){
  const W={impact:0.5,urgency:0.3,effort:0.2};
  const SLA={critical:4,high:24,medium:72,low:168};
  function clamp(n,a,b){return Math.max(a,Math.min(b,n));}
  function score(t){
    const i=clamp(Number(t.impact)||0,1,10);
    const u=clamp(Number(t.urgency)||0,1,10);
    const e=clamp(Number(t.effort)||0,1,10);
    const s=+(i*W.impact+u*W.urgency+(11-e)*W.effort).toFixed(2);
    return s;
  }
  function priority(s){
    if(s>=8) return 'critical';
    if(s>=6) return 'high';
    if(s>=4) return 'medium';
    return 'low';
  }
  function slaDeadline(createdAt, pri){
    const h=SLA[pri]||SLA.low;
    return new Date(new Date(createdAt).getTime()+h*3600000);
  }
  function isBreached(t, now=new Date()){
    if(t.resolvedAt) return false;
    const s=score(t), p=priority(s);
    const dl=slaDeadline(t.createdAt,p);
    return new Date(now) > dl;
  }
  function rank(tasks, now=new Date()){
    return [...tasks].map(t=>{
      const s=score(t), p=priority(s), breached=isBreached(t,now);
      return {...t,score:s,priority:p,breached,deadline:slaDeadline(t.createdAt,p)};
    }).sort((a,b)=> (b.breached-a.breached) || (b.score-a.score));
  }
  function createTask(o){
    return {id:o.id||Math.random().toString(36).slice(2,7),title:o.title||'Untitled',impact:o.impact,urgency:o.urgency,effort:o.effort,createdAt:o.createdAt||new Date().toISOString(),resolvedAt:o.resolvedAt||null};
  }
  const AppCore={W,SLA,score,priority,slaDeadline,isBreached,rank,createTask};
  if(typeof module!=='undefined') module.exports=AppCore;
  g.AppCore=AppCore;
})(typeof globalThis!=='undefined'?globalThis:this);

// Isomorphic facade — Node require('./domain.js') and browser global SprintDomain.
(function (root) {
  const domain = (typeof module !== 'undefined' && module.exports)
    ? require('./domain.js')
    : root.SprintDomain;
  const api = { TaskPriorityEngine: domain.TaskPriorityEngine };
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = api;
  }
  if (typeof globalThis !== 'undefined') {
    globalThis.AppCore = api;
  } else if (root) {
    root.AppCore = api;
  }
})(typeof globalThis !== 'undefined' ? globalThis : this);

